CREATE SEQUENCE truss.complete_feed_consumer_row_seq AS bigint MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE; CREATE TABLE truss.complete_feed_consumer (storage_row_id bigint PRIMARY KEY DEFAULT nextval('truss.complete_feed_consumer_row_seq'), source_epoch text NOT NULL COLLATE pg_catalog."C", feed_profile text NOT NULL COLLATE pg_catalog."C", scope_identity text NOT NULL COLLATE pg_catalog."C", consumer_id text NOT NULL COLLATE pg_catalog."C", registration_id text NOT NULL COLLATE pg_catalog."C", worker_generation bigint NOT NULL, state_kind text NOT NULL COLLATE pg_catalog."C", consumer_identity_bytes bytea NOT NULL, consumer_identity_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(consumer_identity_bytes)) STORED, original_registration_bytes bytea NOT NULL, current_state_bytes bytea NOT NULL, current_state_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(current_state_bytes)) STORED, applied_boundary_bytes bytea, applied_boundary_profile_bytes bytea, inclusive_protection_xid xid8 NOT NULL, protection_evidence_bytes bytea NOT NULL, procedure_profile_bytes bytea NOT NULL, downstream_profile_bytes bytea NOT NULL, registered_at timestamptz NOT NULL, acknowledged_at timestamptz, CONSTRAINT complete_feed_consumer_counter_domain CHECK (storage_row_id > 0 AND worker_generation >= 0), CONSTRAINT complete_feed_consumer_state CHECK (state_kind IN ('awaiting_seed', 'active', 'removed')), CONSTRAINT complete_feed_consumer_originals CHECK (octet_length(source_epoch) > 0 AND octet_length(feed_profile) > 0 AND octet_length(scope_identity) > 0 AND octet_length(consumer_id) > 0 AND octet_length(registration_id) > 0 AND octet_length(consumer_identity_bytes) > 0 AND octet_length(original_registration_bytes) > 0 AND octet_length(current_state_bytes) > 0 AND octet_length(protection_evidence_bytes) > 0 AND octet_length(procedure_profile_bytes) > 0 AND octet_length(downstream_profile_bytes) > 0), CONSTRAINT complete_feed_consumer_boundary_pair CHECK ((applied_boundary_bytes IS NULL) = (applied_boundary_profile_bytes IS NULL)), CONSTRAINT complete_feed_consumer_boundary_nonempty CHECK (applied_boundary_bytes IS NULL OR (octet_length(applied_boundary_bytes) > 0 AND octet_length(applied_boundary_profile_bytes) > 0)), CONSTRAINT complete_feed_consumer_awaiting CHECK (state_kind <> 'awaiting_seed' OR (applied_boundary_bytes IS NULL AND acknowledged_at IS NULL)), CONSTRAINT complete_feed_consumer_active CHECK (state_kind <> 'active' OR applied_boundary_bytes IS NOT NULL)); CREATE INDEX complete_feed_consumer_identity_route ON truss.complete_feed_consumer USING btree (consumer_identity_sha256, storage_row_id)